// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 465;
draw.viewbox(0, 0, W, H);

var SERIF = "Georgia, 'Times New Roman', serif";
var LX = 30, RX = 570, BOT = 400, TOPL = 30;      // trapezoid corners
var OBJ = { x: 92, y: 95, r: 45 };                 // actual object (far left corner)
var RECTL = 178, RECTR = 560, RECTT = 180;         // perceived (dashed) rectangle
var state = { skew: 25, pinX: 400, overlay: 'Both' };
var dragging = false;

function topRightY() { return TOPL + state.skew * 4; }   // 30 (rectangle) … 210 (max skew)

function svgClientX(clientX) {
  var pt = draw.node.createSVGPoint();
  pt.x = clientX; pt.y = 0;
  var m = draw.node.getScreenCTM();
  if (!m) return state.pinX;
  return pt.matrixTransform(m.inverse()).x;
}

document.addEventListener('pointermove', function (e) {
  if (!dragging) return;
  state.pinX = Math.max(70, Math.min(555, svgClientX(e.clientX)));
  render();
});
document.addEventListener('pointerup', function () { dragging = false; });

function tangentPoints(P, C, r) {
  var dx = P.x - C.x, dy = P.y - C.y;
  var d = Math.hypot(dx, dy);
  if (d <= r + 1) return null;
  var g = Math.atan2(dy, dx), del = Math.acos(r / d);
  return [g + del, g - del].map(function (a) {
    return { x: C.x + r * Math.cos(a), y: C.y + r * Math.sin(a) };
  });
}

function label(el, tip, popTitle, popBody) {
  el.css('cursor', 'pointer');
  if (tip) el.on('mousemove', function (e) { showTooltip(tip, e); })
           .on('mouseleave', function () { hideTooltip(); });
  if (popTitle) el.on('click', function () { showPopup(popTitle, popBody); });
  return el;
}

function serif(t, size) {
  return t.font({ family: SERIF, style: 'italic', size: size })
          .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

function render() {
  draw.clear();
  var ty = topRightY();
  var P = { x: state.pinX, y: BOT };
  var showA = state.overlay !== 'Perceived only';
  var showP = state.overlay !== 'Actual only';
  var dx = OBJ.x - P.x, dy = OBJ.y - P.y;

  /* ── Actual trapezoidal room ─────────────────────────────────────── */
  if (showA) {
    var trap = draw.polygon([[LX, BOT], [LX, TOPL], [RX, ty], [RX, BOT]])
      .fill('#ffffff').stroke({ color: '#000', width: 3 });
    label(trap, 'Actual room: a trapezoid, not a rectangle',
      'Actual room floor plan',
      'The real room is trapezoidal: the left corner is much farther from the pinhole than the right corner. Viewed through this one pinhole it casts exactly the same image as an ordinary rectangular room.');

    // rotated label along the slanted top wall
    var deg = Math.atan2(ty - TOPL, RX - LX) * 180 / Math.PI;
    var nx = (ty - TOPL), ny = -(RX - LX), nl = Math.hypot(nx, ny);
    var lx = (LX + RX) / 2 + nx / nl * 20, ly = (TOPL + ty) / 2 + ny / nl * 20;
    serif(draw.text('Actual room floor plan'), 22)
      .attr({ 'text-anchor': 'middle', x: lx, y: ly, transform: 'rotate(' + deg + ' ' + lx + ' ' + ly + ')' });
  }

  /* ── Perceived rectangular room (dashed) ─────────────────────────── */
  if (showP) {
    var pr = draw.rect(RECTR - RECTL, BOT - RECTT).move(RECTL, RECTT)
      .fill('none').stroke({ color: '#000', width: 2.5, dasharray: '10,7' });
    label(pr, 'The rectangular room the viewer assumes',
      'Perceived room floor plan',
      'The brain assumes an ordinary rectangular room. Both plans produce the identical image at the pinhole — a single 2D projection cannot tell a skewed trapezoid from a rectangle.');
    serif(draw.text('Perceived room floor plan'), 22)
      .attr({ 'text-anchor': 'middle', x: 370, y: RECTT - 8 });
  }

  /* ── Sight rays (belong to the real geometry) ────────────────────── */
  if (showA) {
    // thin black ray: pinhole → perceived object → actual object → far wall
    var s = (P.x > OBJ.x + 5) ? (P.x - LX) / (P.x - OBJ.x) : 1.3;
    if (s < 1.05 || s > 2.2) s = 1.3;
    var eB = { x: P.x + s * dx, y: P.y + s * dy };
    draw.line(P.x, P.y, eB.x, eB.y).stroke({ color: '#000', width: 1.5 });

    // two red rays grazing the actual object
    var T = tangentPoints(P, OBJ, OBJ.r);
    if (T) {
      for (var i = 0; i < 2; i++) {
        var ex = T[i].x + (T[i].x - P.x) * 0.28, ey = T[i].y + (T[i].y - P.y) * 0.28;
        var ray = draw.line(P.x, P.y, ex, ey).stroke({ color: '#e00', width: 3 });
        label(ray, 'Sight lines from the pinhole grazing the far object', null, null);
      }
    }
  }

  /* ── Objects ─────────────────────────────────────────────────────── */
  if (showA) {
    var c1 = draw.circle(OBJ.r * 2).center(OBJ.x, OBJ.y)
      .fill('#b8b8b8').stroke({ color: '#000', width: 3 });
    label(c1, 'Actual object — far left corner',
      'Actual object (far corner)',
      'This object stands deep in the far corner of the trapezoid. It is physically identical to the object in the near right corner, but much farther from the pinhole.');

    var c2 = draw.circle(88).center(538, (ty + BOT) / 2)
      .fill('#b8b8b8').stroke({ color: '#000', width: 3 });
    label(c2, 'Identical object — near right corner',
      'Identical object (near corner)',
      'This identical object stands in the near right corner. From the pinhole it subtends the SAME visual angle as the far object — the red sight lines bracket both.');
  }

  if (showP) {
    var sp = Math.max(0.3, Math.min(0.95, (P.x - RECTL) / (P.x - OBJ.x)));
    var pcx = P.x + sp * dx, pcy = P.y + sp * dy, prad = OBJ.r * sp;
    var c3 = draw.circle(prad * 2).center(pcx, pcy)
      .fill('#b8b8b8').stroke({ color: '#000', width: 2.5, dasharray: '6,5' });
    label(c3, 'Where the brain places the far object',
      'Perceived object',
      'Assuming a rectangular room, the brain localizes the far object here, on the dashed plan. Having misjudged its distance, it reads the identical object as smaller — the Ames room illusion.');
    serif(draw.text('Perceived'), 22).attr({ x: 38, y: 256 });
    serif(draw.text('object'), 22).attr({ x: 66, y: 282 });
  }

  /* ── Pinhole (draggable) ─────────────────────────────────────────── */
  var pin = draw.polygon([[P.x - 8, BOT], [P.x + 8, BOT], [P.x, BOT - 16]]).fill('#000');
  var hit = draw.circle(40).center(P.x, BOT - 4).fill('#000').opacity(0).css('cursor', 'ew-resize');
  hit.on('pointerdown', function (e) { dragging = true; e.preventDefault(); });
  hit.on('mousemove', function (e) { showTooltip('Drag me along the wall — the illusion works from only ONE viewpoint', e); })
     .on('mouseleave', function () { hideTooltip(); });
  serif(draw.text('Pinhole'), 22)
    .attr({ 'text-anchor': 'middle', x: Math.max(70, Math.min(530, P.x)), y: 436 });
}

/* ── Controls ──────────────────────────────────────────────────────── */
function update_skewAngle(v) { state.skew = v; render(); }

function set_planOverlay(m) {
  state.overlay = m;
  var map = { 'Both': 'ovBothBtn', 'Actual only': 'ovActualBtn', 'Perceived only': 'ovPerceivedBtn' };
  for (var k in map) document.getElementById(map[k]).className = (state.overlay === k) ? 'active' : '';
  render();
}

/* ── Demo step player ──────────────────────────────────────────────── */
var demoSteps = [
  { title: 'Two plans, one image',
