  if (dx < 0) t = Math.min(t, (2 - P.x) / dx);
  if (dx > 0) t = Math.min(t, (W - 2 - P.x) / dx);
  if (dy > 0) t = Math.min(t, (H - 2 - P.y) / dy);
  if (!isFinite(t) || t <= 0) t = 1.2;
  return { x: P.x + dx * t * 0.995, y: P.y + dy * t * 0.995 };
