    serif(draw.text('Actual room floor plan'), 24, false)
      .attr({ 'text-anchor': 'middle', x: lx, y: ly, transform: 'rotate(' + deg + ' ' + lx + ' ' + ly + ')' });
  }

  /* ── Perceived rectangular room (dashed, fixed) ──────────────────── */
  if (showP) {
    var pr = draw.rect(RECTR - RECTL, BOT - RECTT).move(RECTL, RECTT)
      .fill('none').stroke({ color: '#000', width: 2.5, dasharray: '12,8' });
