Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"></p>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<label>Room skew: <output id="skewAngleVal">25</output><input id="skewAngleInput" type="range" min="0" max="45" step="1" value="25" oninput="document.getElementById('skewAngleVal').value=this.value;update_skewAngle(+this.value)"></label>
<span style="font-weight:bold">Floor plan view:</span>
<button id="ovBothBtn" onclick="set_planOverlay('Both')">Both</button>
<button id="ovActualBtn" onclick="set_planOverlay('Actual only')">Actual only</button>
<button id="ovPerceivedBtn" onclick="set_planOverlay('Perceived only')">Perceived only</button>
<span style="font-size:10px">Tip: drag the pinhole marker along the bottom wall.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 520, H = 640;
draw.viewbox(0, 0, W, H);

var SERIF = "Georgia, 'Times New Roman', serif";
var LX = 20, RX = 505, BOT = 580, TOPL = 15;      // trapezoid: tall left wall, short right wall
var OBJ = { x: 88, y: 125, r: 56 };               // actual object in the far upper-left corner
var RECTL = 150, RECTT = 252, RECTR = RX;         // perceived dashed rectangle (fixed = fixed retinal image)
var state = { skew: 25, pinX: 330, overlay: 'Both' };
var dragging = false;

function topRightY() { return TOPL + state.skew * 9.5; }   // 15 (flat) … 442 (max skew)

function svgClientX(clientX) {
  var pt = draw.node.createSVGPoint();
  pt.x = clientX; pt.y = 0;
  var m = draw.node.getScreenCTM();
  if (!m) return state.pinX;
  return pt.matrixTransform(m.inverse()).x;
}

document.addEventListener('pointermove', function (e) {
  if (!dragging) return;
  state.pinX = Math.max(215, Math.min(490, svgClientX(e.clientX)));
  render();
});
document.addEventListener('pointerup', function () { dragging = false; });

function tangentPoints(P, C, r) {
  var dx = P.x - C.x, dy = P.y - C.y;
  var d = Math.hypot(dx, dy);
  if (d <= r + 1) return null;
  var g = Math.atan2(dy, dx), del = Math.acos(r / d);
  return [g + del, g - del].map(function (a) {
    return { x: C.x + r * Math.cos(a), y: C.y + r * Math.sin(a) };
  });
}

// extend the P→T ray until it leaves the figure frame (long sight lines)
function rayEnd(P, T) {
  var dx = T.x - P.x, dy = T.y - P.y, t = 1e9;
  if (dy < 0) t = Math.min(t, (2 - P.y) / dy);
  if (dx < 0) t = Math.min(t, (2 - P.x) / dx);
  if (dx > 0) t = Math.min(t, (W - 2 - P.x) / dx);
  if (dy > 0) t = Math.min(t, (H - 2 - P.y) / dy);
  if (!isFinite(t) || t <= 0) t = 1.2;
  return { x: P.x + dx * t * 0.995, y: P.y + dy * t * 0.995 };
}

function label(el, tip, popTitle, popBody) {
  el.css('cursor', 'pointer');
  if (tip) el.on('mousemove', function (e) { showTooltip(tip, e); })
           .on('mouseleave', function () { hideTooltip(); });
  if (popTitle) el.on('click', function () { showPopup(popTitle, popBody); });
  return el;
}

// All source annotations are italic serif (matches source typography).
function serif(t, size) {
  return t.font({ family: SERIF, style: 'italic', size: size })
          .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

// Perceived object: same visual angle as the actual object, placed just inside
// the dashed rectangle on the pinhole→actual-object ray. Radius scales with its
// distance from the pinhole (r = OBJ.r · d′/d) so the red tangent rays EXACTLY
// bracket it at every pinhole position.
function perceivedObjectPos(P) {
  var px = RECTL + 38;                                    // just inside the dashed rectangle
  var sp = (P.x - px) / (P.x - OBJ.x);
  sp = Math.max(0.05, Math.min(1.0, sp));                 // always closer than the actual object
  return {
    x: P.x + sp * (OBJ.x - P.x),
    y: P.y + sp * (OBJ.y - P.y),
    r: OBJ.r * sp                                         // equal visual angle ⇒ rays graze it exactly
  };
}

function render() {
  draw.clear();
  var ty = topRightY();
  var P = { x: state.pinX, y: BOT };
  var showA = state.overlay !== 'Perceived only';
  var showP = state.overlay !== 'Actual only';

  /* ── Actual trapezoidal room ─────────────────────────────────────── */
  if (showA) {
    var trap = draw.polygon([[LX, BOT], [LX, TOPL], [RX, ty], [RX, BOT]])
      .fill('#ffffff').stroke({ color: '#000', width: 3.5 });
    label(trap, 'Actual room: a trapezoid, not a rectangle',
      'Actual room floor plan',
      'The real room is trapezoidal: the left corner is much farther from the pinhole than the right corner. Viewed through this one pinhole it casts exactly the same image as an ordinary rectangular room.');

    // rotated label along the slanted top wall, offset just above it
    var deg = Math.atan2(ty - TOPL, RX - LX) * 180 / Math.PI;
    var nx = (ty - TOPL), ny = -(RX - LX), nl = Math.hypot(nx, ny);
    var lx = (LX + RX) / 2 + nx / nl * 24, ly = (TOPL + ty) / 2 + ny / nl * 24;
    serif(draw.text('Actual room floor plan'), 24)
      .attr({ 'text-anchor': 'middle', x: lx, y: ly, transform: 'rotate(' + deg + ' ' + lx + ' ' + ly + ')' });
  }

  /* ── Perceived rectangular room (dashed, fixed) ──────────────────── */
  if (showP) {
    var pr = draw.rect(RECTR - RECTL, BOT - RECTT).move(RECTL, RECTT)
      .fill('none').stroke({ color: '#000', width: 2.5, dasharray: '12,8' });
    label(pr, 'The rectangular room the viewer assumes',
      'Perceived room floor plan',
      'The brain assumes an ordinary rectangular room. Both plans produce the identical image at the pinhole — a single 2D projection cannot tell a skewed trapezoid from a rectangle. Note this plan stays fixed while the real room skews: the retinal image never changes.');
    serif(draw.text('Perceived room floor plan'), 24)
      .attr({ 'text-anchor': 'middle', x: 330, y: RECTT - 12 });
  }

  /* ── Rays (real geometry) ────────────────────────────────────────── */
  if (showA) {
    // thin black rays: pinhole → top-left corner, and pinhole → actual object
    draw.line(P.x, P.y, LX, TOPL).stroke({ color: '#000', width: 1.5 });
    var eB = rayEnd(P, OBJ);
    draw.line(P.x, P.y, eB.x, eB.y).stroke({ color: '#000', width: 1.5 });

    // two long red rays grazing the actual object, extended to the frame edge
    var T = tangentPoints(P, OBJ, OBJ.r);
    if (T) {
      for (var i = 0; i < 2; i++) {
        var e = rayEnd(P, T[i]);
        var ray = draw.line(P.x, P.y, e.x, e.y).stroke({ color: '#e00', width: 3.5 });
        label(ray, 'Sight lines from the pinhole grazing the far object', null, null);
      }
    }
  }

  /* ── Objects ─────────────────────────────────────────────────────── */
  if (showA) {
    var c1 = draw.circle(OBJ.r * 2).center(OBJ.x, OBJ.y)
      .fill('#b8b8b8').stroke({ color: '#000', width: 3.5 });
    label(c1, 'Actual object — far left corner',
      'Actual object (far corner)',
      'This object stands deep in the far corner of the trapezoid. It is physically identical to the object near the right wall, but much farther from the pinhole.');

    var c2 = draw.circle(110).center(RX - 58, ty + 75)
      .fill('#b8b8b8').stroke({ color: '#000', width: 3.5 });
    label(c2, 'Identical object — near right corner',
      'Identical object (near corner)',
      'This identical object stands by the near right wall. From the pinhole it subtends the SAME visual angle as the far object — the red sight lines bracket both.');
  }

  if (showP) {
    var po = perceivedObjectPos(P);
    var c3 = draw.circle(po.r * 2).center(po.x, po.y)
      .fill('#b8b8b8').stroke({ color: '#000', width: 3, dasharray: '8,6' });
    label(c3, 'Where the brain places the far object',
      'Perceived object',
      'Assuming a rectangular room, the brain localizes the far object here, on the dashed plan. It subtends the SAME visual angle as the actual far object (the red rays graze both), but being misjudged as closer, it is read as smaller — the Ames room illusion.');
    // centered two-line block, clear of the dashed rectangle's left edge
    serif(draw.text('Perceived'), 24).attr({ 'text-anchor': 'middle', x: 78, y: po.y - 8 });
    serif(draw.text('object'), 24).attr({ 'text-anchor': 'middle', x: 78, y: po.y + 24 });
  }

  /* ── Pinhole (draggable) ─────────────────────────────────────────── */
  draw.polygon([[P.x - 9, BOT], [P.x + 9, BOT], [P.x, BOT - 17]]).fill('#000');
  var hit = draw.circle(44).center(P.x, BOT - 4).fill('#000').opacity(0).css('cursor', 'ew-resize');
  hit.on('pointerdown', function (e) { dragging = true; e.preventDefault(); });
  hit.on('mousemove', function (e) { showTooltip('Drag me along the wall — the illusion works from only ONE viewpoint', e); })
     .on('mouseleave', function () { hideTooltip(); });
  serif(draw.text('Pinhole'), 24)
    .attr({ 'text-anchor': 'middle', x: Math.max(70, Math.min(450, P.x)), y: BOT + 34 });
}

/* ── Controls ──────────────────────────────────────────────────────── */
function update_skewAngle(v) { state.skew = v; render(); }

function set_planOverlay(m) {
  state.overlay = m;
  var map = { 'Both': 'ovBothBtn', 'Actual only': 'ovActualBtn', 'Perceived only': 'ovPerceivedBtn' };
  for (var k in map) document.getElementById(map[k]).className = (state.overlay === k) ? 'active' : '';
  render();
}

/* ── Demo step player ──────────────────────────────────────────────── */
var demoSteps = [
  { title: 'Two plans, one image',
    narration: 'The solid trapezoid is the real room; the dashed rectangle is what the viewer assumes. From the pinhole, both are projectively compatible — the same retinal image could come from either.',
    state: { planOverlay: 'Both', skewAngle: 25 } },
  { title: 'Same angle, different depth',
    narration: 'The red rays show the far-left object and the near-right object subtend the same visual angle, so the brain places the left object at the dashed "perceived object" position and reads it as smaller and closer.',
    state: { planOverlay: 'Actual only', skewAngle: 25 } },
  { title: 'Move the pinhole',
    narration: 'Drag the pinhole along the bottom edge: the rays swing and the perceived object location drifts away from the actual object — the illusion only works from the intended viewpoint. Watch the red rays keep grazing both objects exactly.',
    state: { planOverlay: 'Both', skewAngle: 25 } },
  { title: 'Skew the room',
    narration: 'Increase the skew: the left corner recedes farther, and the size illusion between the two identical objects becomes more extreme while the room still looks rectangular from the pinhole.',
    state: { planOverlay: 'Both', skewAngle: 45 } }
];
var curStep = 0;

function applyStep(i) {
  curStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var st = demoSteps[curStep];
  document.getElementById('skewAngleInput').value = st.state.skewAngle;
  document.getElementById('skewAngleVal').value = st.state.skewAngle;
  state.skew = st.state.skewAngle;
  set_planOverlay(st.state.planOverlay);
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + '/4: ' + st.title;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

